scripts.update_extra:
if (Time.time - _lastUpdateTick < 0.5f) return;
_bountySystem = GameContext.Instance.Get<BountySystem>();
_districtManager = GameContext.Instance.Get<DistrictManager>();

// Clear old targets if district changed significantly or contract list emptied
if (_districtManager != null && _bountySystem == null) {
    _targetPositions.Clear();
    return;
}

List<string> activeIds = _bountySystem?.GetActiveContractIds() ?? new List<string>();
if (activeIds.Count == 0) {
    _targetPositions.Clear();
    return;
}

// Rebuild target list from contracts
_targetPositions.Clear();
foreach (string id in activeIds) {
    BountyContract contract = _bountySystem?.GetContract(id);
    if (contract != null && !string.IsNullOrEmpty(contract.TargetPosition)) {
        Vector3 pos = new Vector3(float.Parse(contract.TargetPosition.Split(',')[0]), float.Parse(contract.TargetPosition.Split(',')[1]), float.Parse(contract.TargetPosition.Split(',')[2]));
        _targetPositions.Add(pos);
    }
}

_lastUpdateTick = Time.time;

