    if (distanceToTarget <= _lockOnRadius) {
      Quaternion targetRotation = Quaternion.LookRotation(lookDir + transform.up * 0.5f);
      transform.rotation = Quaternion.Slerp(transform.rotation, targetRotation, Time.deltaTime * 3f);
    }
  }
}

